SELECT ws.ws_item_sk, SUM(ws.ws_net_profit) AS total_sales_profit, COALESCE(SUM(cr.cr_net_loss), 0) AS total_return_loss, SUM(ws.ws_net_profit) - COALESCE(SUM(cr.cr_net_loss), 0) AS net_profit_after_returns, CASE WHEN SUM(ws.ws_net_profit) - COALESCE(SUM(cr.cr_net_loss), 0) > 5000 THEN 'High' WHEN SUM(ws.ws_net_profit) - COALESCE(SUM(cr.cr_net_loss), 0) BETWEEN 1000 AND 5000 THEN 'Medium' ELSE 'Low' END AS profit_category, DENSE_RANK() OVER (ORDER BY SUM(ws.ws_net_profit) - COALESCE(SUM(cr.cr_net_loss), 0) DESC) AS profit_rank FROM web_sales ws LEFT JOIN catalog_returns cr ON ws.ws_order_number = cr.cr_order_number AND ws.ws_item_sk = cr.cr_item_sk LEFT JOIN reason r ON cr.cr_reason_sk = r.r_reason_sk LEFT JOIN household_demographics hd_bill ON ws.ws_bill_hdemo_sk = hd_bill.hd_demo_sk LEFT JOIN household_demographics hd_ship ON ws.ws_ship_hdemo_sk = hd_ship.hd_demo_sk WHERE ws.ws_sold_date_sk BETWEEN 19990101 AND 19991231 GROUP BY ws.ws_item_sk
